  public static func createTBS(
    _ fbb: inout FlatBufferBuilder,
    IDOffset ID: Offset,
    NATIVE_IDOffset NATIVE_ID: Offset = Offset(),
    RADIO: tbsRadioClass = .unknown,
    MCC: UInt32 = 0,
    MNC: UInt32 = 0,
    LAC: UInt32 = 0,
    TAC: UInt32 = 0,
    CELL_IDOffset CELL_ID: Offset = Offset(),
    LATITUDE: Double = 0.0,
    LONGITUDE: Double = 0.0,
    RANGE_M: Double = 0.0,
    SAMPLES: UInt32 = 0,
    AVERAGE_SIGNAL_DBM: Double = 0.0,
    FIRST_OBSERVEDOffset FIRST_OBSERVED: Offset = Offset(),
    LAST_OBSERVEDOffset LAST_OBSERVED: Offset = Offset(),
    OPERATOROffset OPERATOR: Offset = Offset(),
    FREQUENCY_MHZ: Double = 0.0,
    SITE_NAMEOffset SITE_NAME: Offset = Offset(),
    COUNTRY_CODEOffset COUNTRY_CODE: Offset = Offset(),
    SOURCESVectorOffset SOURCES: Offset,
    CONSENSUSOffset CONSENSUS: Offset
  ) -> Offset {
    let __start = TBS.startTBS(&fbb)
    TBS.add(ID: ID, &fbb)
    TBS.add(NATIVE_ID: NATIVE_ID, &fbb)
    TBS.add(RADIO: RADIO, &fbb)
    TBS.add(MCC: MCC, &fbb)
    TBS.add(MNC: MNC, &fbb)
    TBS.add(LAC: LAC, &fbb)
    TBS.add(TAC: TAC, &fbb)
    TBS.add(CELL_ID: CELL_ID, &fbb)
    TBS.add(LATITUDE: LATITUDE, &fbb)
    TBS.add(LONGITUDE: LONGITUDE, &fbb)
    TBS.add(RANGE_M: RANGE_M, &fbb)
    TBS.add(SAMPLES: SAMPLES, &fbb)
    TBS.add(AVERAGE_SIGNAL_DBM: AVERAGE_SIGNAL_DBM, &fbb)
    TBS.add(FIRST_OBSERVED: FIRST_OBSERVED, &fbb)
    TBS.add(LAST_OBSERVED: LAST_OBSERVED, &fbb)
    TBS.add(OPERATOR: OPERATOR, &fbb)
    TBS.add(FREQUENCY_MHZ: FREQUENCY_MHZ, &fbb)
    TBS.add(SITE_NAME: SITE_NAME, &fbb)
    TBS.add(COUNTRY_CODE: COUNTRY_CODE, &fbb)
    TBS.addVectorOf(SOURCES: SOURCES, &fbb)
    TBS.add(CONSENSUS: CONSENSUS, &fbb)
    return TBS.endTBS(&fbb, start: __start)
  }

