    try _v.visit(field: VT.MCC, fieldName: "MCC", required: false, type: UInt32.self)
    try _v.visit(field: VT.MNC, fieldName: "MNC", required: false, type: UInt32.self)
    try _v.visit(field: VT.LAC, fieldName: "LAC", required: false, type: UInt32.self)
    try _v.visit(field: VT.TAC, fieldName: "TAC", required: false, type: UInt32.self)
    try _v.visit(field: VT.CELL_ID, fieldName: "CELL_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.LATITUDE, fieldName: "LATITUDE", required: false, type: Double.self)
    try _v.visit(field: VT.LONGITUDE, fieldName: "LONGITUDE", required: false, type: Double.self)
    try _v.visit(field: VT.RANGE_M, fieldName: "RANGE_M", required: false, type: Double.self)
    try _v.visit(field: VT.SAMPLES, fieldName: "SAMPLES", required: false, type: UInt32.self)
    try _v.visit(field: VT.AVERAGE_SIGNAL_DBM, fieldName: "AVERAGE_SIGNAL_DBM", required: false, type: Double.self)
    try _v.visit(field: VT.FIRST_OBSERVED, fieldName: "FIRST_OBSERVED", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.LAST_OBSERVED, fieldName: "LAST_OBSERVED", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.OPERATOR, fieldName: "OPERATOR", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FREQUENCY_MHZ, fieldName: "FREQUENCY_MHZ", required: false, type: Double.self)
    try _v.visit(field: VT.SITE_NAME, fieldName: "SITE_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COUNTRY_CODE, fieldName: "COUNTRY_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SOURCES, fieldName: "SOURCES", required: true, type: ForwardOffset<Vector<ForwardOffset<TBSProvenance>, TBSProvenance>>.self)
    try _v.visit(field: VT.CONSENSUS, fieldName: "CONSENSUS", required: true, type: ForwardOffset<TBSConsensus>.self)
